func (idb *InsightsDB) GetBranchTip(ctx context.Context) (string, error) {
	var tip string
	err := idb.db.QueryRowContext(ctx,
		"SELECT value FROM cache_meta WHERE key = ?",
		"branch_tip",
	).Scan(&tip)
	if err == sql.ErrNoRows {
		return "", nil
	}
	if err != nil {
		return "", fmt.Errorf("get branch tip: %w", err)
	}
	return tip, nil
}

