	var count int
	err := idb.db.QueryRowContext(ctx,
		"SELECT COUNT(*) FROM sessions WHERE checkpoint_id = ?",
		checkpointID,
	).Scan(&count)
	if err != nil {
		return false, fmt.Errorf("check checkpoint existence: %w", err)
